import random, time
def call_with_retry(fn, tries=5, base=0.2, cap=5.0):
    for n in range(tries):
        try: return fn()
        except Exception:
            if n == tries - 1: raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** n)))   # exponential backoff with full jitter

